onfig) { setupLog.Info("disabling http/2") c.NextProtos = []string{"http/1.1"} } if !enableHTTP2 { tlsOpts = append(tlsOpts, disableHTTP2) } // 创建用于指标和 Webhook 证书的监视器 var metricsCertWatcher, webhookCertWatcher *certwatcher.CertWatcher // 初始Webhook TLS选项 webhookTLSOpts := tlsOpts if len(webhookCertPath) > 0 { setupLog.Info("使用提供的证书初始化 Webhook 证书监视器", "webhook-cert-path", webhookCertPath, "webhook-cert-name", webhookCertName, "webhook-cert-key", webhookCertKey) var err error webhookCertWatcher, err = certwatcher.New( filepath.Join(webhookCertPath, webhookCertName), filepath.Join(webhookCertPath, webhookCertKey), ) if err != nil { setupLog.Error(err, "Failed to initialize webhook certificate watcher") os.Exit(1) } webhookTLSOpts = append(webhookTLSOpts, func(config *tls.Config) { config.GetCertificate = webhookCertWatcher.GetCertificate }) } webhookServer := webhook.NewServer(webhook.Options{ TLSOpts: webhookTLSOpts, }) // 指标端点在 'config/default/kustomization.yaml' 中启用。指标选项配置服务器。 // 更多信息： // - https://pkg.go.dev/sigs.k8s.io/controller-runtime@v0.20.4/pkg/metrics/server // - https://book.kubebuilder.io/reference/metrics.html metricsServerOptions := metricsserver.Options{ BindAddress: metricsAddr, SecureServing: secureMetrics, TLSOpts: tlsOpts, } if secureMetrics { // FilterProvider 用于通过认证和授权来保护指标端点。 // 这些配置确保只有授权用户和服务账户 // 可以访问指标端点。RBAC 配置在 'config/rbac/kustomization.yaml' 中。更多信息： // https://pkg.go.dev/sigs.k8s.io/controller-runtime@v0.20.4/pkg/metrics/filters#WithAuthenticationAndAuthorization metricsServerOptions.FilterProvider = filters.WithAuthenticationAndAuthorization } // 如果未指定证书，controller-runtime 将自动 // 为指标服务器生成自签名证书。虽然对于开发和测试来说很方便， // 但这种设置不建议用于生产环境。 // // TODO(用户)：如果您启用 certManager，请取消注释以下行： // - [METRICS-WITH-CERTS] 在 config/default/kustomization.yaml 中生成并使用 // 由 cert-manager 管理的指标服务器证书。 // - [PROMETHEUS-WITH-CERTS] 在 config/prometheus/kustomization.yaml 中用于 TLS 认证。 if len(metricsCertPath) > 0 { setupLog.Info("使用提供的证书初始化指标证书监视器", "metrics-cert-path", metricsCertPath, "metrics-cert-name", metricsCertName, "metrics-cert-key", metricsCertKey) var err error metricsCertWatcher, err = certwatcher.New( filepath.Join(metricsCertPath, metricsCertName), filepath.Join(metricsCertPath, metricsCertKey), ) if err != nil { setupLog.Error(err, "to initialize metrics certificate watcher", "error", err) os.Exit(1) } metricsServerOptions.TLSOpts = append(metricsServerOptions.TLSOpts, func(config *tls.Config) { config.GetCertificate = metricsCertWatcher.GetCertificate }) } mgr, err := ctrl.NewManager(ctrl.GetConfigOrDie(), ctrl.Options{ Scheme: scheme, Metrics: metricsServerOptions, WebhookServer: webhookServer, HealthProbeBindAddress: probeAddr, LeaderElection: enableLeaderElection, LeaderElectionID: "4b13cc52.example.com", // LeaderElectionReleaseOnCancel 定义了当管理器结束时，领导者是否应自愿辞职 // 当管理器停止时，这要求二进制文件立即结束，否则这个设置是不安全的。设置这个可以显著 // 加快自愿领导者的过渡，因为新的领导者不必首先等待 // LeaseDuration 时间。 // // 在提供的默认脚手架中，程序会在 // 管理器停止后立即结束，因此启用此选项是可以的。不过， // 如果您正在进行或打算在管理器停止后执行任何操作，如执行清理， // 那么使用它可能是不安全的。 // LeaderElectionReleaseOnCancel: true, }) if err != nil { setupLog.Error(err, "unable to start manager") os.Exit(1) } if err = (&controller.MemcachedReconciler{ Client: mgr.GetClient(), Scheme: mgr.GetScheme(), }).SetupWithManager(mgr); err != nil { setupLog.Error(err, "unable to create controller", "controller", "Memcached") os.Exit(1) } // +kubebuilder:scaffold:builder if metricsCertWatcher != nil { setupLog.Info("Adding metrics certificate watcher to manager") if err := mgr.Add(metricsCertWatcher); err != nil { setupLog.Error(err, "unable to add metrics certificate watcher to manager") os.Exit(1) } } if webhookCertWatcher != nil { setupLog.Info("Adding webhook certificate watcher to manager") if err := mgr.Add(webhookCertWatcher); err != nil { setupLog.Error(err, "unable to add webhook certificate watcher to manager") os.Exit(1) } } if err := mgr.AddHealthzCheck("healthz", healthz.Ping); err != nil { setupLog.Error(err, "unable to set up health check") os.Exit(1) } if err := mgr.AddReadyzCheck("readyz", healthz.Ping); err != nil { setupLog.Error(err, "unable to set up ready check") os.Exit(1) } setupLog.Info("starting manager") if err := mgr.Start(ctrl.SetupSignalHandler()); err != nil { setupLog.Error(err, "problem running manager") os.Exit(1) }
}

