使用 Kubebuilder 创建的项目可以启用 metrics 和 cert-manager 选项。请注意，当我们使用 ENV TEST 时，我们旨在测试控制器及其调整过程。这被视为集成测试，因为 ENV TEST API 会在集群中进行测试，因此会下载并使用二进制文件来配置其前置要求。然而，其主要目的是对控制器进行 单元 测试。 因此，在常见情况下，测试对账时您不需要关注这些选项。但是，如果您希望在安装了 Prometheus 和 Cert-manager 的情况下进行测试，可以在运行测试之前添加安装它们所需的步骤。以下是一个示例。 // 在测试之前添加安装 Prometheus operator 和 cert-manager 的操作。 BeforeEach(func() { By("installing prometheus operator") Expect(utils.InstallPrometheusOperator()).To(Succeed()) By("installing the cert-manager") Expect(utils.InstallCertManager()).To(Succeed()) }) // 您也可以在测试后将它们移除:: AfterEach(func() { By("uninstalling the Prometheus manager bundle") utils.UninstallPrometheusOperManager() By("uninstalling the cert-manager bundle") utils.UninstallCertManager() }) 请检查以下示例，了解如何实现上述操作： const ( prometheusOperatorVersion = "0.51" prometheusOperatorURL = "https://raw.githubusercontent.com/prometheus-operator/" + "prometheus-operator/release-%s/bundle.yaml" certmanagerVersion = "v1.5.3" certmanagerURLTmpl = "https://github.com/cert-manager/cert-manager/releases/download/%s/cert-manager.yaml"
) func warnError(err error) { _, _ = fmt.Fprintf(GinkgoWriter, "warning: %v\n", err)
} // InstallPrometheusOperator 安装 prometheus 操作器，用于导出启用的指标。func InstallPrometheusOperator() error { url := fmt.Sprintf(prometheusOperatorURL, prometheusOperatorVersion) cmd := exec.Command("kubectl", "apply", "-f", url) _, err := Run(cmd) return err
} // UninstallPrometheusOperator 卸载 Prometheusfunc UninstallPrometheusOperator() { url := fmt.Sprintf(prometheusOperatorURL, prometheusOperatorVersion) cmd := exec.Command("kubectl", "delete", "-f", url) if _, err := Run(cmd); err != nil { warnError(err) }
} // UninstallCertManager 卸载证书管理器func UninstallCertManager() { url := fmt.Sprintf(certmanagerURLTmpl, certmanagerVersion) cmd := exec.Command("kubectl", "delete", "-f", url) if _, err := Run(cmd); err != nil { warnError(err) }
} // InstallCertManager 安装证书管理器包。func InstallCertManager() error { url := fmt.Sprintf(certmanagerURLTmpl, certmanagerVersion) cmd := exec.Command("kubectl", "apply", "-f", url) if _, err := Run(cmd); err != nil { return err } // 等待 cert-manager-webhook 准备就绪，如果在集群上卸载后重新安装 cert-manager，可能需要一些时间。	cmd = exec.Command("kubectl", "wait", "deployment.apps/cert-manager-webhook", "--for", "condition=Available", "--namespace", "cert-manager", "--timeout", "5m", ) _, err := Run(cmd) return err
} // LoadImageToKindClusterWithName 将本地 Docker 镜像加载到 Kind 集群中func LoadImageToKindClusterWithName(name string) error { cluster := "kind" if v, ok := os.LookupEnv("KIND_CLUSTER"); ok { cluster = v } kindOptions := []string{"load", "docker-image", name, "--name", cluster} cmd := exec.Command("kind", kindOptions...) _, err := Run(cmd) return err
} 然而，请注意，对于指标和cert-manager的测试可能更适合作为端到端（e2e）测试，而不是在使用ENV TEST进行控制器测试时进行的测试。您可以查看在 Operator-SDK 仓库中实施的 示例示例 ，了解如何编写e2e测试以确保您项目的基本工作流程。此外，请注意，您可以在已配置集群上运行测试，使用现有集群进行测试的选项。 testEnv = &envtest.Environment{ UseExistingCluster: true,
} Setup ENV TEST tool
